function Tabzy(id,options={}){this.opt=Object.assign({panelDisplay:"block",hash:false},options);this._container=document.getElementById(id);if(!this._container){throw new Error(`Tabzy Error: Element with id "${id}" not found.`)}this._tabs=Array.from(this._container.querySelectorAll("li a[href]"));if(this._tabs.length===0){throw new Error(`Tabzy: no <li> children found inside #${id}.`)}const panels=this._tabs.map(tab=>this._getPanel(tab)).filter(Boolean);if(this._tabs.length!==panels.length){throw new Error(`Tabzy Error: Mismatch between tabs and panels. Found ${panels.length} panels for ${this._tabs.length} tabs. `+`Ensure every <li> has an <a href="#panelId"> that matches an existing panel element (id="panelId").`)}this._init()}Tabzy.prototype._init=function(){let startTab=this._tabs[0].closest("li");if(this.opt.hash){const currentHash=window.location.hash;if(currentHash){const tabLink=this._container.querySelector(`a[href='${currentHash}']`);if(tabLink){startTab=tabLink.closest("li")}}}this._currentTab=startTab;this._classNames=("tabzy--active "+(this.opt.cssClass??"")).trim();this._boundHandleClick=this._handleClick.bind(this);this._container.addEventListener("click",this._boundHandleClick);this._boundHashChange=this._handleHashChange.bind(this);if(this.opt.hash){window.addEventListener("hashchange",this._boundHashChange)}this._addClassName();this._renderState()};Tabzy.prototype._handleHashChange=function(){this.switch(window.location.hash||`${this._tabs[0].getAttribute("href")}`)};Tabzy.prototype._addClassName=function(){this._classNames.split(" ").forEach(className=>{this._currentTab.classList.add(className)})};Tabzy.prototype._removeClassName=function(){this._classNames.split(" ").forEach(className=>{this._currentTab.classList.remove(className)})};Tabzy.prototype._renderState=function(){this._tabs.forEach(tab=>{const panel=this._getPanel(tab);if(!panel)return;if(tab.closest("li").classList.contains("tabzy--active")){panel.style.display=this.opt.panelDisplay}else{panel.style.display="none"}})};Tabzy.prototype._getPanel=function(tab){const panelId=tab.getAttribute("href");const panel=document.querySelector(panelId);return panel};Tabzy.prototype.switch=function(id){let tabLink;if(id.startsWith("#")){tabLink=this._container.querySelector(`[href='${id}']`)}else{tabLink=this._container.querySelector(`[href='#${id}']`)}if(!tabLink)return;const targetTab=tabLink.closest("li");if(!targetTab||targetTab===this._currentTab)return;this._removeClassName();this._currentTab=targetTab;this._addClassName();this._renderState();if(this.opt.hash){window.location.hash=tabLink.getAttribute("href").slice(1)}};Tabzy.prototype.destroy=function(){this._removeClassName();this._tabs.forEach(tab=>{const panel=this._getPanel(tab);if(panel){panel.style.cssText=""}});this._container.removeEventListener("click",this._boundHandleClick);window.removeEventListener("hashchange",this._boundHashChange);this._currentTab=null;this._tabs=null;this._container=null};Tabzy.prototype._handleClick=function(e){const tabLink=e.target.closest("a[href]");if(tabLink){e.preventDefault();if(this.opt.hash){window.location.hash=tabLink.getAttribute("href").slice(1)}else{const currentTabId=tabLink.getAttribute("href");this.switch(currentTabId)}}};